 "carry": [
  {
   "h": "Handle with care (adults first)",
   "items": [
    "Trafficking, missing relatives and partner violence are present in families students meet. **Never ask a family about them.** These questions go to QP staff.",
    "Do not use stories of abuse or disappearance to make the trip feel serious. They belong to the people who lived them."
   ]
  },
  {
   "h": "Framings that would be disrespectful or turn the trip into poverty tourism",
   "items": [
    "Children as suffering. The partner's and teachers' experience: students meet children *more free than they are*.",
    "Asking families to explain their poverty. Structural questions go to QP staff, never to the families.",
    "Photographing people as scenery; photographing inside homes or at religious practice without asking.",
    "Calling people poor but happy (romanticizing) and why don't they just… (demonizing).",
    "Treating Pachamama or Apu offerings as superstition, or as a threat to Catholic faith, in student or parent material.",
    "Using QP's donor language (impact, transform) as if it were the community's own description.",
    "The structure decides everything — it erases the people working on the door."
   ]
  }
 ],
 "labs": [
  {
   "key": "A",
   "title": "Two ways to count a child",
   "question": "How many young children in Peru have anemia — and who decides?",
   "changes": "the method (MINSA 2022 rule vs WHO 2024 guideline); altitude; urban/rural; year (2023 Cusco vs 2025 national).",
   "data": "ENDES 2025 national 43.4% vs 34.9% (rural 50.4% vs 43.2%); ENDES 2023 Cusco 49.9% (urban 50.3, rural 49.5); iron supplementation 38.7% (2025).",
   "notice": "the same children produce two prevalence rates; at 10,500 ft the altitude adjustment is a decision with consequences; urban Cusco was not better.",
   "yourCall": "If you were writing a grant, a news story, or a report card for the government, which number would you use — and is choosing it honest?",
   "denverRun": "lead lines — 60,000–64,000 estimated, 36,000+ replaced. Which neighborhoods get replaced first, and who decides?"
  },
  {
   "key": "B",
   "title": "Sell now or wait?",
   "question": "Why does growing more potatoes not mean earning more?",
   "changes": "days to wait before selling (spoilage); whether you make *chuño*; distance to a road; whether you can see the Lima price; number of buyers who show up.",
   "data": "S/2.01 → 3.36 → 4.63 chain (Jan 2023, ratio only); S/1.37/kg national 2022 average; verified absence of real-time farm-gate prices.",
   "notice": "information and time are what the farmer lacks, not skill; *chuño* changes the game; the 2023 levels are a crisis month.",
   "yourCall": "If publishing farm-gate prices in real time would cost almost nothing, why hasn't it happened — and whose job is it?"
  },
  {
   "key": "C",
   "title": "Three fields or one?",
   "question": "Is a family with scattered plots worse off, or smarter?",
   "changes": "one 2.3 ha plot vs three ~0.8 ha plots at different altitudes; frost and hail events by altitude band; title / no title; borrowing.",
   "data": "CENAGRO 2012 — 2.7 parcels, 0.8 ha each, 2.3 ha cropland, 52% of owners untitled; *ayni* labor exchange as a variable.",
   "notice": "fragmentation is crop insurance; the same scattering that protects the harvest blocks credit; *ayni* lets a family harvest fields it could not work alone.",
   "yourCall": "If someone offered to consolidate this family's land into one titled plot, what would they gain and what would they lose?"
  },
  {
   "key": "D",
   "title": "The job offer",
   "question": "Why would a careful, loving father say yes to a job he knows little about?",
   "changes": "the wage offered; the job (miner, cook, general work); who made the offer (relative, agency in Cusco, stranger on the road); whether there's a contract; bus fare paid up front or not; how many weeks the farm can run without him.",
   "data": "farm day labor S/120–150/week vs S/1,200–3,600/month in a mining unit (Basombrío 2021); minimum wage S/1,230 (Oct 2026); recruitment by job offer 71–78% of trafficking cases; the Urcos–Inambari road, 205 km.",
   "notice": "the offer is rational; the risk sits in what the family *cannot know* — who the recruiter is, whether the job exists, whom to call if he disappears.",
   "yourCall": "What would a family need to know before saying yes — and whose job is it to make that knowable?",
   "denverRun": "the same offer at a Denver hiring corner — 62% of surveyed day laborers had been cheated of wages (DU, 2016–17). What can a worker here check that a worker on the Interoceánica can't?"
  },
  {
   "key": "E",
   "title": "One bad week",
   "question": "The same thing happens to three families. Why does it cost them so differently?",
   "changes": "paid leave yes/no; health coverage and distance to care; savings in a bank; the loan rate available (from 2c); life insurance; who they can call.",
   "data": "every row of 2c.",
   "notice": "the event is luck; the price is mostly built. Count the cushions each family had, and who built each one.",
   "yourCall": "Which of your family's cushions did you earn, and which were built around you? What would it take to build one there?"
  }
 ],
 "theology": {
  "readings": [
   "**Gustavo Gutiérrez, *We Drink from Our Own Wells* (1983).** Peru's own theologian (d. 2024): the spirituality of the poor is a well, not a lack; the visitor comes to drink, not to dig. Pair with QP's *riysisaq*.",
   "The Vilcanota glaciers are that paragraph with a name.",
   "**St. Josephine Bakhita** (feast 8 Feb, World Day of Prayer against Human Trafficking) — enslaved as a child, freed, canonized. For Barrier 9: the Church names trafficked people as saints-in-waiting, not as statistics."
  ],
  "question": "The people here have kept their language, their land arrangements and their faith through 450 years of being told they were wrong. What do they know that I have never had to learn — and will I let them teach me?"
 },
